compile.workshop:
variables {
    global:
        0: a
        1: i
    player:
        0: p
}

rule ("global 1d") {
    event {
        Ongoing - Global;
    }
    actions {
        Modify Global Variable(a, Remove From Array By Index, 0);
    }
}

rule ("player 1d") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Modify Player Variable(Event Player, p, Remove From Array By Index, 0);
    }
}

rule ("global 2d") {
    event {
        Ongoing - Global;
    }
    actions {
        Modify Global Variable At Index(a, Global.i, Remove From Array By Index, 0);
    }
}

rule ("global 3d") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable At Index(a, Global.i, Append To Array(Array(Filtered Array(First Of(Value In Array(Global.a, Global.i)), Compare(Current Array Index, !=, 0))), Array Slice(Value In Array(Global.a, Global.i), 1, 999999999999)));
    }
}

rule ("literal 3d") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable At Index(a, 0, Append To Array(Append To Array(Array Slice(First Of(Global.a), 0, 1), Array(Filtered Array(Value In Array(First Of(Global.a), 1), Compare(Current Array Index, !=, 2)))), Array Slice(First Of(Global.a), 2, 999999999999)));
    }
}

rule ("global 4d") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable At Index(a, 0, Append To Array(Append To Array(Array Slice(First Of(Global.a), 0, 1), Array(Append To Array(Append To Array(Array Slice(Value In Array(First Of(Global.a), 1), 0, 2), Array(Filtered Array(Value In Array(Value In Array(First Of(Global.a), 1), 2), Compare(Current Array Index, !=, 3)))), Array Slice(Value In Array(First Of(Global.a), 1), 3, 999999999999)))), Array Slice(First Of(Global.a), 2, 999999999999)));
    }
}

rule ("random leaf 3d") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable At Index(a, 0, Append To Array(Array(Filtered Array(First Of(First Of(Global.a)), Compare(Current Array Index, !=, Random Integer(0, 1)))), Array Slice(First Of(Global.a), 1, 999999999999)));
    }
}

